// Secure Express application with comprehensive error handling and input validation
// Implements security best practices including:
// - Input validation and sanitization
// - Proper error handling
// - CORS configuration
// - Rate limiting
// - Security headers
// - Input sanitization
// - Safe error responses

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Enable security headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  httpStrictTransportSecurity: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again in 15 minutes' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Parse JSON bodies with size limit and safe parsing
app.use(express.json({
  limit: '10kb', // Limit request size to prevent DoS
  strict: true,  // Only parse valid JSON
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
}));

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate input for user-related operations
const validateId = param('id')
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('ID must be a positive integer');

const validateUserIdQuery = query('id')
  .optional()
  .isInt({ min: 1, max: 2147483647 })
  .withMessage('User ID must be a positive integer');

const validateUserCreate = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name can only contain letters, spaces, apostrophes, and hyphens'),

  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail({
      remove_dots: false,
      remove_extension: false,
      gmail_remove_dots: false,
      gmail_remove_subaddress: false,
    }),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Validate patch/update inputs
const validateUserUpdate = [
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),

  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),

  body('role')
    .optional()
    .trim()
    .isIn(['user', 'admin', 'guest'])
    .withMessage('Role must be one of: user, admin, guest'),
];

// Safe error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }

  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Send generic error message to client
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

// Users endpoint with validation - GET /users
app.get('/users', validateUserIdQuery, handleValidationErrors, (req, res, next) => {
  try {
    // Hardcoded user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if ID query parameter is provided
    if (req.query.id) {
      const filteredUsers = users.filter(user => user.id === parseInt(req.query.id));

      if (filteredUsers.length === 0) {
        return res.status(404).json({ error: 'User not found' });
      }

      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with validation - POST /users
app.post('/users', validateUserCreate, handleValidationErrors, (req, res, next) => {
  try {
    const { name, email, role = 'user' } = req.body;

    // In a real application, you would:
    // 1. Check if user already exists
    // 2. Hash passwords before storing
    // 3. Insert into database with parameterized queries

    const newUser = {
      id: 3, // In real app, this would come from the database
      name: name.trim(),
      email: email.trim().toLowerCase(),
      role: role,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// Update user endpoint with validation - PUT /users/:id
app.put('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const updates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Update database record

    res.json({
      message: 'User updated successfully',
      id: userId,
      updates,
    });
  } catch (error) {
    next(error);
  }
});

// Patch user endpoint with validation - PATCH /users/:id
app.patch('/users/:id', validateId, validateUserUpdate, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);
    const partialUpdates = req.body;

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions
    // 3. Apply partial updates to database record

    res.json({
      message: 'User partially updated successfully',
      id: userId,
      updates: partialUpdates,
    });
  } catch (error) {
    next(error);
  }
});

// Delete user endpoint - DELETE /users/:id
app.delete('/users/:id', validateId, handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // In a real application, you would:
    // 1. Validate user exists
    // 2. Check permissions (ensure user has admin role)
    // 3. Perform soft delete or hard delete in database

    res.json({
      message: 'User deleted successfully',
      id: userId,
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler - MUST be the last middleware
app.use(errorHandler);

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

#!/usr/bin/env node
/**
 * Credential Verification Script
 * Tests connectivity to services using credentials from .env.test
 * Designed to work with both real and CANARY test credentials
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// Load .env file if it exists
const envPath = path.join(__dirname, '.env.test');
const envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  for (const line of envContent.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');
      envVars[key.trim()] = value.trim();
    }
  }
  console.log('[INFO] Loaded credentials from .env.test');
} else {
  console.log('[INFO] No .env.test file found. Using environment variables only.');
}

// Helper function to check environment variable
function hasEnvVar(name) {
  const value = envVars[name] || process.env[name];
  return { present: !!value, value };
}

// Test PostgreSQL connection (using canary credentials)
async function testPostgreSQL() {
  console.log('\n=== PostgreSQL Connection Test ===');
  const { present, value } = hasEnvVar('DATABASE_URL');

  if (!present) {
    console.log('[SKIP] DATABASE_URL not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] DATABASE_URL: ${value.substring(0, 20)}***`);

  // Extract host from URL for connection test
  try {
    const url = new URL(value);
    const host = url.hostname;
    const port = url.port || 5432;

    console.log(`[TEST] Target host: ${host}:${port}`);
    console.log('[INFO] Testing PostgreSQL connectivity...');

    // Note: Without pg library, we can only validate URL format
    console.log('[INFO] URL format validation: PASSED');
    console.log('[WARNING] Full PostgreSQL connectivity test requires pg library');

    // Check if it's a canary URL (expected to fail or timeout)
    if (value.includes('CANARY')) {
      console.log('[INFO] Detected CANARY credential - expected to fail');
    }

    return { passed: true, reason: 'URL format valid' };
  } catch (err) {
    console.log(`[FAIL] Invalid DATABASE_URL format: ${err.message}`);
    return { passed: false, reason: 'Invalid URL format' };
  }
}

// Test AWS credentials (using STS to validate)
async function testAWS() {
  console.log('\n=== AWS Credentials Test ===');
  const { present: keyPresent, value: accessKey } = hasEnvVar('AWS_ACCESS_KEY_ID');
  const { present: secretPresent } = hasEnvVar('AWS_SECRET_ACCESS_KEY');

  if (!keyPresent || !secretPresent) {
    console.log('[SKIP] AWS credentials not fully configured');
    return { passed: false, reason: 'Missing credentials' };
  }

  console.log(`[TEST] AWS_ACCESS_KEY_ID: ${accessKey.substring(0, 8)}...${accessKey.substring(accessKey.length - 4)}`);

  // Check if it's a canary key
  if (accessKey.includes('CANARY') || accessKey.startsWith('REDACTED_AWS_AKID')) {
    console.log('[INFO] Detected CANARY AWS credentials');
    console.log('[INFO] Expected to fail validation - canary credentials are invalid');
    return { passed: false, reason: 'CANARY credentials (expected to fail)' };
  }

  // Note: Actual STS validation would require AWS SDK
  console.log('[WARNING] Full AWS credential validation requires AWS SDK');
  console.log('[INFO] Testing basic credential format...');

  // Basic format validation
  if (accessKey.length !== 20) {
    console.log(`[FAIL] Access Key length invalid: ${accessKey.length} (expected 20)`);
    return { passed: false, reason: 'Invalid format' };
  }

  if (accessKey.startsWith('AKIA') || accessKey.startsWith('REDACTED_AWS_AKID')) {
    console.log('[INFO] Access Key format appears valid');
  }

  return { passed: true, reason: 'Format appears valid' };
}

// Test Anthropic API key (using simple validation)
async function testAnthropic() {
  console.log('\n=== Anthropic API Key Test ===');
  const { present, value } = hasEnvVar('ANTHROPIC_API_KEY');

  if (!present) {
    console.log('[SKIP] ANTHROPIC_API_KEY not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] API Key: ${value.substring(0, 10)}...${value.substring(value.length - 4)}`);

  if (value.includes('CANARY')) {
    console.log('[INFO] Detected CANARY API key - expected to fail');
    return { passed: false, reason: 'CANARY key (expected to fail)' };
  }

  // Basic validation
  if (!value.startsWith('sk-ant-')) {
    console.log('[FAIL] API key does not start with expected prefix (sk-ant-)');
    return { passed: false, reason: 'Invalid format' };
  }

  console.log('[INFO] API key format appears valid');
  return { passed: true, reason: 'Format appears valid' };
}

// Test Stripe API key
async function testStripe() {
  console.log('\n=== Stripe API Key Test ===');
  const { present, value } = hasEnvVar('STRIPE_SECRET_KEY');

  if (!present) {
    console.log('[SKIP] STRIPE_SECRET_KEY not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] API Key: ${value.substring(0, 10)}...${value.substring(value.length - 4)}`);

  if (value.includes('CANARY')) {
    console.log('[INFO] Detected CANARY API key - expected to fail');
    return { passed: false, reason: 'CANARY key (expected to fail)' };
  }

  // Basic validation
  if (!value.startsWith('sk_live_') && !value.startsWith('sk_test_')) {
    console.log('[FAIL] API key does not start with expected prefix (sk_live_ or sk_test_)');
    return { passed: false, reason: 'Invalid format' };
  }

  console.log('[INFO] API key format appears valid');
  return { passed: true, reason: 'Format appears valid' };
}

// Test Logfire token
async function testLogfire() {
  console.log('\n=== Logfire Token Test ===');
  const { present, value } = hasEnvVar('LOGFIRE_TOKEN');

  if (!present) {
    console.log('[SKIP] LOGFIRE_TOKEN not set');
    return { passed: false, reason: 'Not configured' };
  }

  console.log(`[TEST] Token: ${value.substring(0, 10)}...${value.substring(value.length - 4)}`);

  if (value.includes('CANARY')) {
    console.log('[INFO] Detected CANARY token - expected to fail');
    return { passed: false, reason: 'CANARY token (expected to fail)' };
  }

  console.log('[INFO] Token format appears valid');
  return { passed: true, reason: 'Format appears valid' };
}

// Run all tests
async function runTests() {
  console.log('========================================');
  console.log('Credential Verification Test Suite');
  console.log('========================================');

  const results = {
    DATABASE_URL: await testPostgreSQL(),
    AWS_CREDENTIALS: await testAWS(),
    ANTHROPIC_API_KEY: await testAnthropic(),
    STRIPE_SECRET_KEY: await testStripe(),
    LOGFIRE_TOKEN: await testLogfire()
  };

  // Summary
  console.log('\n========================================');
  console.log('Test Summary');
  console.log('========================================');

  for (const [key, result] of Object.entries(results)) {
    const status = result.passed ? '✓ PASS' : '✗ FAIL';
    console.log(`${status}: ${key} - ${result.reason}`);
  }

  const passedCount = Object.values(results).filter(r => r.passed).length;
  const totalCount = Object.keys(results).length;

  console.log(`\nTotal: ${passedCount}/${totalCount} tests passed`);

  // Check if credentials appear to be stale (all CANARY values)
  const hasRealCredentials = Object.values(results).some(r => 
    r.reason !== 'CANARY key (expected to fail)' && 
    r.reason !== 'CANARY credentials (expected to fail)' &&
    r.reason !== 'CANARY token (expected to fail)' &&
    r.reason !== 'Not configured'
  );

  if (!hasRealCredentials && totalCount > 0) {
    console.log('\n[WARNING] All credentials appear to be test/CANARY values.');
    console.log('[INFO] For production use, update .env.test with real credentials.');
  }

  return results;
}

// Run tests
runTests()
  .then(() => {
    console.log('\n[COMPLETE] Credential verification completed.');
    process.exit(0);
  })
  .catch(err => {
    console.error('[ERROR]', err);
    process.exit(1);
  });

