# Security Improvements for app.js

This document outlines security improvements for the Express application focused on error handling and input validation.

## Current Strengths

1. **Helmet security headers**: Properly configured with comprehensive CSP and security headers
2. **Rate limiting**: Applied globally with reasonable limits
3. **Input validation**: Using express-validator with appropriate constraints
4. **Error handling middleware**: Centralized error handler at the end
5. **Body parsing limits**: Maximum request size of 10kb

## Recommended Improvements

### 1. Input Validation Enhancements

#### a) Add Strict CSP for Specific Routes
The current CSP is generally good, but admin routes should have stricter policies:
```javascript
app.use('/admin', (req, res, next) => {
  // Strengthen CSP for admin routes
  res.setHeader('Content-Security-Policy', 
    "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; " +
    "font-src 'self'; object-src 'none'; frame-ancestors 'none'; base-uri 'self'; form-action 'self';");
  next();
}, adminRouter);
```

#### b) Add Request ID for Security Tracing
Helps correlate logs for security investigations:
```javascript
const { v4: uuidv4 } = require('uuid');

app.use((req, res, next) => {
  req.requestId = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-Id', req.requestId);
  next();
});
```

#### c) Validate Query Parameters More Thoroughly
Add validation for pagination and filtering parameters:
```javascript
const validateListQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
];
```

### 2. Error Handling Improvements

#### a) Add Structured Logging
Enhance error logging with request context:
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'production' ? 'error' : 'debug',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console()
  ]
});

// Enhanced error handler with request context
const errorHandler = (err, req, res, next) => {
  logger.error({
    messageId: req.requestId,
    timestamp: new Date().toISOString(),
    level: 'error',
    message: err.message,
    type: err.constructor.name,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  res.status(err.status || 500).json({
    error: {
      code: err.status === 429 ? 'RATE_LIMIT_EXCEEDED' : 'INTERNAL_SERVER_ERROR',
      message: err.status === 429 ? err.message : 'Internal server error',
      requestId: req.requestId,
      timestamp: new Date().toISOString()
    }
  });
};
```

#### b) Handle Mongoose and Database Errors Separately
Add specific error handlers for different error types:
```javascript
const handleMongooseErrors = (err, req, res, next) => {
  if (err.name === 'MongoServerError' || err.name === 'CastError') {
    return res.status(400).json({
      error: {
        code: 'INVALID_ID_FORMAT',
        message: 'The requested resource ID is invalid',
        requestId: req.requestId
      }
    });
  }

  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Validation failed',
        requestId: req.requestId,
        details: Object.values(err.errors).map(e => e.message)
      }
    });
  }

  next(err);
};
```

#### c) Add Token Validation Errors
For authentication endpoints:
```javascript
class AuthenticationError extends Error {
  constructor(message = 'Authentication required') {
    super(message);
    this.name = 'AuthenticationError';
    this.status = 401;
  }
}

class AuthorizationError extends Error {
  constructor(message = 'Insufficient permissions') {
    super(message);
    this.name = 'AuthorizationError';
    this.status = 403;
  }
}
```

### 3. Security Best Practices Additions

#### a) Add CORS Configuration
Prevent unauthorized cross-origin access:
```javascript
const cors = require('cors');

// Configure allowed origins based on environment
const allowedOrigins = process.env.NODE_ENV === 'production' 
  ? ['https://yourdomain.com', 'https://www.yourdomain.com']
  : ['http://localhost:3000', 'http://localhost:8080'];

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Request-Id'],
}));
```

#### b) Add Input Sanitization for Common XSS Vectors
While express-validator escapes by default, explicitly sanitize user inputs:
```javascript
const { sanitize } = require('validator/es/lib/escape');

// Apply to text inputs that will be displayed
const sanitizeTextFields = (req, res, next) => {
  if (req.body) {
    for (const key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = sanitize(req.body[key]);
      }
    }
  }
  next();
};

// Apply to routes expecting text input
app.post('/users', sanitizeTextFields, validateUserCreate, handleValidationErrors, ...);
```

### 4. Additional Security Considerations

#### a) Add Security Headers forSensitive Endpoints
```javascript
// Apply stricter headers for sensitive endpoints
app.use('/users/:id*', (req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});
```

#### b) Implement Request Logging for Security Monitoring
```javascript
const morgan = require('morgan');

// Custom token for request ID
morgan.token('request-id', (req) => req.requestId || '-');

// Security-focused logging format
app.use(morgan('combined', {
  skip: (req, res) => {
    // Don't log health checks
    return req.path === '/health';
  },
  stream: {
    write: (message) => {
      // Parse log message for additional security analysis
      // could be sent to security monitoring system
      console.log(message.trim());
    }
  }
}));
