  server.close(() => { ... }); // ❌ 'server' is undefined here
});

const server = app.listen(3000, () => { ... }); // Declared AFTER usage
```
**Fix:**
```javascript
// Move server declaration before SIGTERM handler
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Then add SIGTERM handler
```

