# Security Improvements for app.js
## Error Handling & Input Validation Focus

This document provides targeted security improvements for the Express application in app.js.

---

## Critical Security Issues

### 1. Information Disclosure in Error Logs

**Current Code:**
```javascript
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });
  // ...
};
```

**Issue:** Stack traces should never be logged in any environment as they can expose file paths, library versions, and implementation details.

**Fix:**
```javascript
const errorHandler = (err, req, res, next) => {
  // Log only non-sensitive error information
  console.error('Error in %s %s: %s', req.method, req.path, err.message);

  res.status(err.status || 500).json({
    error: err.message,
  });
};
```

### 2. Validation Logic Error

**Current Code:**
```javascript
body('name')
  .matches(/^[a-zA-Z\s'-]+$/)
```

**Issue:** The hyphen in the regex character class `['-]` creates an invalid range. It should be escaped or placed at the end.

**Fix:**
```javascript
body('name')
  .matches(/^[a-zA-Z\s'-]+$/)
  .withMessage('Name can only contain letters, spaces, apostrophes, and hyphens')
```

### 3. Email Validation Missing Length Limit

**Current Code:**
```javascript
body('email')
  .trim()
  .isEmail()
  .normalizeEmail({
    remove_dots: false,
    remove_extension: false,
  }),
```

**Issue:** No maximum length validation allows for potential DoS attacks with extremely long inputs.

**Fix:**
```javascript
body('email')
  .trim()
  .isEmail()
  .normalizeEmail()
  .isLength({ max: 254 }) // RFC 5321 maximum
  .withMessage('Email must be 254 characters or less'),
```

---

## High Priority Improvements

### 4. Request Size Validation

**Current Code:**
```javascript
app.use(express.json({
  limit: '10kb',
}));
```

**Issue:** Only JSON size is limited, URL-encoded forms have different rules.

**Fix:**
```javascript
app.use(express.json({
  limit: '10kb',
  strict: true,
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 1000,
  strict: true,
}));
```

### 5. Input Sanitization for XSS Prevention

**Recommendation:**
```javascript
const expressSanitizer = require('express-sanitizer');
app.use(expressSanitizer());

// Apply to all text fields
body('name').escape(),
body('bio').optional().escape(),
```

### 6. HTTP-only Cookies for Sessions

**Recommendation:**
```javascript
const session = require('express-session');
app.use(session({
  secret: process.env.SESSION_SECRET,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'strict',
    maxAge: 24 * 60 * 60 * 1000,
  },
}));
```

---

## Additional Security Recommendations

### 7. Request Timeout Protection
```javascript
const timeout = require('req-timeout');
app.use(timeout(30000)); // 30 second timeout
```

### 8. Better 429 Error Handling
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      retryAfter: Math.ceil(rateLimit.windowMs / 1000),
    });
  },
});
```

### 9. Content-Type Validation
```javascript
app.use(express.json({
  verify: (req, res, buf) => {
    if (req.method === 'POST' || req.method === 'PUT' || req.method === 'PATCH') {
      const contentType = req.headers['content-type'];
      if (!contentType || !contentType.includes('application/json')) {
        return res.status(415).json({ error: 'Unsupported Media Type' });
      }
    }
    req.rawBody = buf;
  }
}));
```

### 10. Input Validation Helper

```javascript
// Create a reusable validation helper
const validateField = (field, options = {}) => {
  const validations = [body(field)];

  if (options.required) {
    validations.push(body(field).not().isEmpty());
  }

  if (options.maxLength) {
    validations.push(body(field).isLength({ max: options.maxLength }));
  }

  if (options.minLength) {
    validations.push(body(field).isLength({ min: options.minLength }));
  }

  if (options.format === 'email') {
    validations.push(body(field).isEmail().normalizeEmail());
  }

  if (options.format === 'integer') {
    validations.push(body(field).isInt());
  }

  return validations;
};

// Then use:
...validateField('email', { required: true, maxLength: 254, format: 'email' }),
```

